<style>
  :root{--px-deep:#073f66;--px-blue:#087eae;--px-teal:#16aaa5;--px-ink:#173f59;--px-muted:#6f8797;--px-line:#d3e4eb;--px-soft:#f3f9fb}
  .px-page{padding:20px}.px-hero{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:15px;padding:24px 27px;border-radius:17px;color:#fff;background:linear-gradient(112deg,var(--px-deep),var(--px-blue) 62%,var(--px-teal));box-shadow:0 12px 28px rgba(7,75,107,.17)}.px-hero__main{display:flex;align-items:center;gap:15px}.px-hero__icon{display:grid;place-items:center;width:56px;height:56px;flex:0 0 56px;border:1px solid rgba(255,255,255,.35);border-radius:15px;background:rgba(255,255,255,.12);font-size:24px}.px-hero small{display:block;font-weight:800;letter-spacing:1px}.px-hero h1{margin:1px 0 3px;font-size:26px;font-weight:850}.px-hero p{margin:0;opacity:.92}.px-hero__actions{display:flex;flex-wrap:wrap;gap:8px}.px-hero .btn{border-radius:9px;font-weight:750}
  .px-alert{margin-bottom:13px;border:0;border-radius:11px}.px-toolbar{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;margin-bottom:14px;padding:15px 17px;border:1px solid var(--px-line);border-radius:14px;background:#fff}.px-filter{display:flex;align-items:flex-end;gap:9px}.px-field label{display:block;margin-bottom:5px;color:#31546b;font-size:10px;font-weight:850;letter-spacing:.5px;text-transform:uppercase}.px-field .form-control{height:40px;border-color:#c8dde6;border-radius:9px}.px-toolbar__note{color:var(--px-muted);font-size:11px}.px-toolbar .btn{height:40px;border-radius:9px;font-weight:750}
  .px-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:14px}.px-stat{display:flex;align-items:center;gap:11px;padding:13px 14px;border:1px solid var(--px-line);border-radius:12px;background:#fff}.px-stat i{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;color:var(--px-blue);background:#e3f4f8}.px-stat strong{display:block;color:var(--px-deep);font-size:19px;line-height:1}.px-stat span{color:var(--px-muted);font-size:10px}
  .px-card{overflow:hidden;margin-bottom:14px;border:1px solid var(--px-line);border-radius:15px;background:#fff;box-shadow:0 7px 20px rgba(25,75,100,.055)}.px-card__head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 17px;border-bottom:1px solid var(--px-line);background:#eff9fb}.px-card__head h2{margin:0;color:var(--px-deep);font-size:16px;font-weight:850}.px-card__head p{margin:3px 0 0;color:var(--px-muted);font-size:11px}.px-count{padding:5px 9px;border-radius:18px;color:#087b91;background:#dff3f5;font-size:10px;font-weight:800}.px-table-wrap{overflow:auto}.px-table{min-width:1380px;margin:0}.px-table th{padding:10px 8px!important;border-top:0!important;background:#f7fafb;color:#244a62;font-size:9px;font-weight:850;letter-spacing:.3px;text-transform:uppercase}.px-table td{padding:10px 8px!important;vertical-align:middle!important;color:#294c62;font-size:11px}.px-table tbody tr{border-left:4px solid transparent}.px-row--pending{border-left-color:#f0ad4e!important;background:#fffaf0}.px-row--waiting{border-left-color:#31a4bd!important;background:#f4fbfd}.px-row--active{border-left-color:#e57373!important;background:#fff7f7}.px-row--recovery{border-left-color:#8e67c7!important;background:#faf7ff}.px-row--closed{border-left-color:#58af83!important;background:#f5fcf8}.px-patient{display:block;color:var(--px-deep);font-weight:850}.px-meta{display:block;margin-top:2px;color:#8296a3;font-size:9px}.px-procedures{max-width:230px}.px-procedure{display:block;font-weight:700}.px-procedure+.px-procedure{margin-top:2px;color:#087eae}.px-room-form{display:flex;align-items:center;gap:7px;min-width:165px}.px-room-form .form-control{height:34px;padding:4px 25px 4px 8px;border-radius:7px;font-size:10px;transition:border-color .18s,box-shadow .18s,opacity .18s}.px-room-form .form-control:focus{border-color:#25a2b8;box-shadow:0 0 0 3px rgba(22,170,165,.11)}.px-room-form .form-control:disabled{cursor:wait;opacity:.68}.px-room-state{display:inline-grid;place-items:center;width:18px;flex:0 0 18px;font-size:13px}.px-room-state.is-saving{color:#168ba5}.px-room-state.is-success{color:#2a9b61}.px-room-state.is-error{color:#c44848}.px-status{display:inline-flex;align-items:center;gap:5px;padding:5px 9px;border-radius:18px;font-size:9px;font-weight:850;white-space:nowrap}.px-status--pending{color:#95610a;background:#fff0cd}.px-status--waiting{color:#087188;background:#dff3f7}.px-status--active{color:#a33b3b;background:#fde3e3}.px-status--recovery{color:#65429b;background:#eee5fb}.px-status--closed{color:#26704a;background:#dff4e8}.px-actions{display:flex;gap:5px}.px-actions .btn{border-radius:7px;font-size:10px;white-space:nowrap}.px-empty{padding:42px!important;text-align:center;color:#718b9b}
  .px-meetings{padding:12px 16px}.px-meeting{display:grid;grid-template-columns:150px 1fr 180px 180px;gap:12px;padding:10px 12px;border-bottom:1px solid #e5eef2;color:#35566c;font-size:11px}.px-meeting:last-child{border-bottom:0}.px-meeting strong{color:var(--px-deep)}
  .px-form{padding:18px}.px-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.px-form-group--wide{grid-column:1/-1}.px-form label{display:block;margin-bottom:5px;color:#284f67;font-size:10px;font-weight:850;text-transform:uppercase}.px-form .form-control{min-height:40px;border-color:#c9dce5;border-radius:9px}.px-form-help{margin-top:5px;color:#7b909f;font-size:10px}.px-form .select2-container{display:block;width:100%!important}.px-form .select2-container--bootstrap4 .select2-selection--multiple{min-height:44px!important;padding:3px 7px;border-color:#c9dce5!important;border-radius:9px!important;background:#fff}.px-form .select2-container--bootstrap4.select2-container--focus .select2-selection--multiple{border-color:#37a9be!important;box-shadow:0 0 0 3px rgba(22,170,165,.12)}.px-form .select2-container--bootstrap4 .select2-selection__choice{max-width:calc(100% - 7px);margin:3px 5px 3px 0!important;padding:4px 8px!important;border:1px solid #b9e1e7!important;border-radius:7px!important;color:#12627c!important;background:#e9f7f9!important;font-size:10px;white-space:normal}.px-form .select2-selection__choice__display{word-break:break-word}.px-form .select2-selection__choice__remove{margin-right:5px!important;color:#16879a!important}.px-form .select2-search--inline .select2-search__field{min-width:220px!important;margin-top:7px!important;color:#365b70;font-size:11px}.px-form-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px;padding-top:15px;border-top:1px solid #dfe9ee}.px-form-actions .btn{min-height:40px;border-radius:9px;font-weight:750}.px-patient-banner{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:15px 17px;border-bottom:1px solid var(--px-line);background:#f8fbfc}.px-patient-banner h3{margin:0;color:var(--px-deep);font-size:17px;font-weight:850}.px-patient-banner span{color:var(--px-muted);font-size:11px}.px-info{margin:0 18px 2px;padding:12px 14px;border:1px solid #bee0e8;border-radius:10px;color:#356078;background:#eef9fb;font-size:11px}.px-info--warning{border-color:#f0d6a1;color:#805e1d;background:#fff8e9}.px-form-errors{display:none;margin:12px 18px 0}.px-log-table{min-width:1180px;margin:0}.px-log-table th{background:#f2f8fa;color:#244a62;font-size:9px;text-transform:uppercase}.px-log-table td{vertical-align:middle!important;color:#35566b;font-size:10px}.px-log-desc{color:var(--px-deep);font-weight:800}
  .px-modal-dialog{width:min(1080px,calc(100% - 28px));max-width:1080px;margin:28px auto}.px-modal-shell{overflow:hidden;border:0;border-radius:17px;background:#f5f9fb;box-shadow:0 28px 80px rgba(5,49,75,.32)}.px-modal-head{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:19px 22px;color:#fff;background:linear-gradient(112deg,var(--px-deep),var(--px-blue) 62%,var(--px-teal))}.px-modal-head small{font-size:9px;font-weight:850;letter-spacing:1px}.px-modal-head h3{margin:2px 0;font-size:19px;font-weight:850}.px-modal-head p{margin:0;color:#d8f1f6;font-size:10px}.px-modal-close{display:grid;place-items:center;width:37px;height:37px;flex:0 0 37px;border:1px solid rgba(255,255,255,.5);border-radius:10px;color:#fff;background:rgba(255,255,255,.1)}.px-modal-close:hover{color:var(--px-blue);background:#fff}.px-modal-content{max-height:calc(100vh - 135px);overflow-y:auto;padding:15px}.px-modal-content .px-editor-card{margin:0}.px-modal-loading,.px-modal-error{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;min-height:260px;padding:35px;color:var(--px-deep);text-align:center}.px-modal-loading i,.px-modal-error i{color:var(--px-blue);font-size:28px}.px-modal-error i{color:#c64a4a}
  @media(max-width:1150px){.px-stats{grid-template-columns:repeat(3,1fr)}.px-hero{align-items:flex-start;flex-direction:column}.px-meeting{grid-template-columns:130px 1fr 150px}}
  @media(max-width:700px){.px-page{padding:11px}.px-stats{grid-template-columns:repeat(2,1fr)}.px-toolbar,.px-filter{align-items:stretch;flex-direction:column}.px-filter .btn{width:100%}.px-form-grid{grid-template-columns:1fr}.px-form-group--wide{grid-column:auto}.px-meeting{grid-template-columns:1fr}.px-hero h1{font-size:22px}.px-patient-banner{align-items:flex-start;flex-direction:column}}
</style>
